<?php
namespace App\Http\Controllers\Admin; use App\Domain\WorkProcesses\WorkProcessRegistry; use App\Http\Controllers\Controller; use App\Models\{WorkProcess,WorkProcessDeliverable,WorkProcessStage}; use Illuminate\Http\{RedirectResponse,Request}; use Illuminate\Support\Facades\DB; use Illuminate\Validation\Rule; use Illuminate\Validation\ValidationException; class WorkProcessChildController extends Controller { public function storeStage(Request $request,WorkProcess $workProcess):RedirectResponse{if($workProcess->stages()->count()>=WorkProcessRegistry::MAX_STAGES)throw ValidationException::withMessages(['stage'=>'A maximum of 12 stages is allowed.']);$data=$request->validate(['title'=>['required','string','max:160'],'description'=>['required','string','max:5000'],'duration_text'=>['nullable','string','max:160'],'icon'=>['nullable',Rule::in(WorkProcessRegistry::ICONS)],'is_active'=>['boolean']]);$data['display_order']=(int)$workProcess->stages()->max('display_order')+1;$workProcess->stages()->create($data);return back()->with('status','Stage added.');} public function moveStage(Request $request,WorkProcess $workProcess,WorkProcessStage $stage):RedirectResponse{$this->stage($workProcess,$stage);$this->move($stage,WorkProcessStage::class,'work_process_id',$workProcess->id,$request->validate(['direction'=>['required','in:up,down']])['direction']);return back();} public function destroyStage(WorkProcess $workProcess,WorkProcessStage $stage):RedirectResponse{$this->stage($workProcess,$stage)->delete();$this->normalize(WorkProcessStage::class,'work_process_id',$workProcess->id);return back();} public function storeDeliverable(Request $request,WorkProcess $workProcess,WorkProcessStage $stage):RedirectResponse{$this->stage($workProcess,$stage);if($stage->deliverables()->count()>=WorkProcessRegistry::MAX_DELIVERABLES)throw ValidationException::withMessages(['deliverable'=>'A maximum of 8 deliverables is allowed per stage.']);$data=$request->validate(['title'=>['required','string','max:160'],'description'=>['nullable','string','max:2000'],'is_active'=>['boolean']]);$data['display_order']=(int)$stage->deliverables()->max('display_order')+1;$stage->deliverables()->create($data);return back()->with('status','Deliverable added.');} public function moveDeliverable(Request $request,WorkProcess $workProcess,WorkProcessStage $stage,WorkProcessDeliverable $deliverable):RedirectResponse{$this->deliverable($workProcess,$stage,$deliverable);$this->move($deliverable,WorkProcessDeliverable::class,'work_process_stage_id',$stage->id,$request->validate(['direction'=>['required','in:up,down']])['direction']);return back();} public function destroyDeliverable(WorkProcess $workProcess,WorkProcessStage $stage,WorkProcessDeliverable $deliverable):RedirectResponse{$this->deliverable($workProcess,$stage,$deliverable)->delete();$this->normalize(WorkProcessDeliverable::class,'work_process_stage_id',$stage->id);return back();} private function stage(WorkProcess $process,WorkProcessStage $stage):WorkProcessStage{abort_unless($stage->work_process_id===$process->id,404);return $stage;} private function deliverable(WorkProcess $process,WorkProcessStage $stage,WorkProcessDeliverable $deliverable):WorkProcessDeliverable{$this->stage($process,$stage);abort_unless($deliverable->work_process_stage_id===$stage->id,404);return $deliverable;} private function move($model,string $class,string $column,int $id,string $direction):void{DB::transaction(function()use($model,$class,$column,$id,$direction){$peer=$class::where($column,$id)->where('display_order',$direction==='up'?'<':'>',$model->display_order)->orderBy('display_order',$direction==='up'?'desc':'asc')->first();if($peer){$order=$model->display_order;$model->update(['display_order'=>$peer->display_order]);$peer->update(['display_order'=>$order]);}$this->normalize($class,$column,$id);});} private function normalize(string $class,string $column,int $id):void{$class::where($column,$id)->orderBy('display_order')->orderBy('id')->get()->each(fn($item,$index)=>$item->updateQuietly(['display_order'=>$index+1]));} }
